@pytest.fixture(scope="session")
def request_sender(config: Dict[str, Any]):
    """
    Returns a callable that sends a GET request with simple retry strategy controlled by config.yml.

    Configuration in config.yml (optional):
      test:
        retries: int (default 2)
        retry_backoff_seconds: int/float (default 1)
    """
    test_cfg = (config.get("test") or {})
    retries = int(test_cfg.get("retries", 2))
    backoff = float(test_cfg.get("retry_backoff_seconds", 1.0))

    def sender(fn: Callable[[], Any]) -> Any:
        attempt = 0
        last_exc: Optional[Exception] = None
        while attempt <= retries:
            try:
                return fn()
            except Exception as e:
                last_exc = e
                if attempt == retries:
                    raise
                time.sleep(backoff * (2 ** attempt))
                attempt += 1
        if last_exc:
            raise last_exc

    return sender


