def _build_params_from_record(record: Dict[str, Any], api_key: str) -> Dict[str, Any]:
    """
    Build query parameters from a test data record. The function respects required/optional parameters.

    Notes:
    - We include 'q', 'days', and optional 'hour', 'lang' from test data.
    - To avoid mutually exclusive constraint issues for 'dt' vs 'unixdt', we send neither by default
      for broad compatibility with the live API; the provided sample dates may be out of allowed range
      (today..next 7 days) at runtime and could trigger 400 responses.
    """
    params: Dict[str, Any] = {
        "q": record.get("q"),
        "days": record.get("days"),
        "key": api_key,
    }

    # Include optional parameters only if present in the test data
    if "hour" in record and record["hour"] is not None:
        params["hour"] = record["hour"]
    if "lang" in record and record["lang"] is not None:
        params["lang"] = record["lang"]

    # Intentionally do not include 'dt'/'unixdt' by default to avoid out-of-range failures.
    # If needed, enable either of the following lines, but never both at the same time:
    # if "dt" in record and record["dt"]:
    #     params["dt"] = record["dt"]
    # elif "unixdt" in record and record["unixdt"]:
    #     params["unixdt"] = record["unixdt"]

    return params


