@pytest.mark.usefixtures("api_client")
def test_marine_get_response_schema_and_status(
    api_client,
    valid_api_key: str,
    marine_endpoint: str,
    marine_test_data: List[Dict[str, Any]],
    swagger_validator: SwaggerSchemaValidator,
    request_query_schema: Dict[str, Any],
    response_schemas: Dict[str, Dict[str, Any]],
    request_sender,
):
    """
    Validate GET /v1/marine.json across all table-driven data from marine.json.json:
    - Validate request parameters against request schema before sending.
    - Send request with retries.
    - Assert HTTP status matches the expected statusCode from the test data.
    - Validate response body schema using SwaggerSchemaValidator for applicable status codes.
    """
    if not valid_api_key:
        pytest.skip("Valid API key not configured. Set 'key' in environment or authentication.ApiKeyAuth in config.yml.")

    for idx, record in enumerate(marine_test_data, start=1):
        expected_status = int(record.get("statusCode", 200))

        params = _build_params_from_record(record, valid_api_key)

        # Request validation with SwaggerSchemaValidator
        swagger_validator.validate_with_schema(params, request_query_schema)

        # Send request with retries (GET)
        response = request_sender(lambda: api_client.get(endpoint=marine_endpoint, params=params))

        # Status assertion
        assert response.status_code == expected_status, (
            f"[Case {idx}] Unexpected status code for query={record.get('q')}, "
            f"days={record.get('days')}, expected={expected_status}, got={response.status_code}"
        )

        # Attempt to parse JSON response
        try:
            resp_json = response.json()
        except ValueError as e:
            pytest.fail(f"[Case {idx}] Response is not valid JSON: {e}", pytrace=False)

        # Response validation with SwaggerSchemaValidator
        code_str = str(response.status_code)
        schema = response_schemas.get(code_str)
        if schema is not None:
            swagger_validator.validate_with_schema(resp_json, schema)
        else:
            # If an unexpected status code is returned, fail explicitly with diagnostic info
            pytest.fail(
                f"[Case {idx}] No schema defined for status code {response.status_code}. "
                f"Update response_schemas fixture if this status is expected.",
                pytrace=False,
            )
